Add sequencer uptime check for L2 deployments:

// Sequencer uptime feed (Arbitrum/Optimism specific)
AggregatorV3Interface public sequencerUptimeFeed;

function getPrice() public view returns (uint256) {
// Check sequencer is up
(, int256 answer, uint256 startedAt, , ) = sequencerUptimeFeed.latestRoundData();
bool isSequencerUp = answer == 0;
require(isSequencerUp, "Sequencer is down");

// Check grace period after sequencer restart
uint256 timeSinceUp = block.timestamp - startedAt;
require(timeSinceUp > GRACE_PERIOD_TIME, "Grace period not over");

// Now get price
(, int256 price, , uint256 updatedAt, ) = priceFeed.latestRoundData();
require(block.timestamp - updatedAt < STALENESS_THRESHOLD, "Stale price");
return uint256(price);
}

